  bytAvl     int(10);
  excID      char(7);
  reserved_1 char(1);
  excDta     char(256);
end-ds;

/endif

**free
/if not defined(genLstHdr_t)
/define genLstHdr_t
// ============================================================= *
//   Generic List Header for List APIs                           *
//===============================================================*

dcl-ds genLstHdr_t qualified template;
